const E: Omit<LangMap, 'en'> = { ms: '', tur: '', urd: '', ben: '', fas: '', zh: '', yue: '', ja: '', ru: '', es: '', ko: '', ta: '', si: '' };

export const TOILET_CONTENT = {
  dua_enter_h: { en: `The Du'a Before Entering`, ms: `Doa Sebelum Masuk`, tur: `Girmeden Önceki Duâ`, urd: `داخل ہونے سے پہلے کی دعا`, ben: `প্রবেশের পূর্বের দোয়া`, fas: `دعای پیش از ورود`, zh: `入前之祷`, yue: `入前之禱`, ja: `入る前の祈願`, ru: `Дуа перед входом`, es: `La Du'a antes de entrar`, ko: `들어가기 전의 두아`, ta: `நுழைவதற்கு முன் பிரார்த்தனை`, si: `ඇතුළු වීමට පෙර දුආව` },
  dua_enter_translit: { en: `Allahumma inni a'udhu bika mina-l khubuthi wa-l khaba'ith.`, ms: `Allahumma inni a'udhu bika minal-khubuthi wal-khaba'ith.`, tur: `Allāhümme innî e'ûzü bike mine'l-hubsi ve'l-habâis.`, urd: `اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ۔`, ben: `আল্লাহুম্মা ইন্নি আউযু বিকা মিনাল-খুবুথি ওয়াল-খাবাইথ।`, fas: `اللّهم إنّی أعوذ بک من الخبث والخبائث.`, zh: `安拉呼曼因尼阿吾祖比卡敏勒胡卜西瓦勒哈巴伊什。`, yue: `安拉呼曼因尼阿吾祖比卡敏勒胡卜西瓦勒哈巴伊什。`, ja: `アッラーフンマ・インニー・アウーズビカ・ミナル＝フブシ・ワル＝ハバーイス。`, ru: `Аллахумма инни а'узу бика мина-ль-хубси ва-ль-хаба'ис.`, es: `Al-lahumma inni a'udhu bika min al-khubthi wa-l khaba'ith.`, ko: `알라훔마 인니 아우두 비카 민 알쿠부시 왈카바이스.`, ta: `அல்லாஹும்ம இன்னீ அஊது பிக்க மினல் குபுதி வல் கபாஇத்.`, si: `අල්ලාහුම්ම ඉන්නී අඌඡු බික මිනල් ඛුබුති වල් ඛබාඉත්.` },
  dua_enter_meaning: { en: `O Allah, I seek refuge with You from all impure male and impure female jinn.`, ms: `Ya Allah, aku berlindung kepada-Mu daripada jin lelaki yang kotor dan jin perempuan yang kotor.`, tur: `Allah'ım! Erkek ve dişi bütün pis şeytanlardan sana sığınırım.`, urd: `اے اللہ! میں تیری پناہ چاہتا ہوں ہر ناپاک نر اور ناپاک مادہ جن سے۔`, ben: `হে আল্লাহ! আমি আপনার কাছে সকল অপবিত্র পুরুষ ও নারী জিন থেকে আশ্রয় প্রার্থনা করছি।`, fas: `خدایا! از پلیدی و پلیدها به تو پناه می‌برم.`, zh: `真主啊！我求护于你，免于一切污秽之男女魔灵。`, yue: `真主啊！我求護於你，免於一切污穢之男女魔靈。`, ja: `アッラーよ、われは汚れた男女のジンより御身に加護を求めます。`, ru: `О Аллах! Я прибегаю к Тебе от нечистых джиннов мужского и женского пола.`, es: `¡Oh Al-lah! Me refugio en Ti de todo yinn impuro, macho o hembra.`, ko: `오 알라시여! 저는 모든 부정한 남녀 진으로부터 당신께 피난을 구합니다.`, ta: `யா அல்லாஹ்! அசுத்தமான ஆண் மற்றும் பெண் ஜின்களிடமிருந்து உன்னிடம் அடைக்கலம் தேடுகிறேன்.`, si: `අහෝ අල්ලාහ්! පිරිමි හා ගැහැනු අශුද්ධ ජින්නයන්ගෙන් ඔබ වෙතින් රැකවරණය පතමි.` },
  dua_enter_p: { en: `Said silently before entering the toilet, or before removing clothes if in an open place. The Prophet ﷺ taught this seeking Allah's protection from the impure jinn who frequent such places.`, ms: `Diucapkan secara senyap sebelum masuk ke tandas, atau sebelum menanggalkan pakaian jika berada di tempat terbuka. Nabi ﷺ mengajarkan ini untuk memohon perlindungan Allah daripada jin yang kotor yang sering berkeliaran di tempat-tempat seperti itu.`, tur: `Tuvalete girmeden önce, açık bir yerdeyse elbise çıkarılmadan önce sessizce okunur. Peygamber ﷺ, bu tür yerlere sık uğrayan pis cinlerden Allah'ın korumasını dilemek için bunu öğretmiştir.`, urd: `بیت الخلا میں داخل ہونے سے پہلے، یا کھلی جگہ ہو تو کپڑے اتارنے سے پہلے، خاموشی سے پڑھی جاتی ہے۔ نبی ﷺ نے یہ ان جگہوں پر آنے جانے والے ناپاک جنّات سے اللہ کی حفاظت طلب کرنے کے لیے سکھائی۔`, ben: `শৌচাগারে প্রবেশের পূর্বে অথবা খোলা জায়গা হলে কাপড় খোলার আগে নীরবে পাঠ করা হয়। এই স্থানসমূহে বিচরণকারী অপবিত্র জিন থেকে আল্লাহর সুরক্ষা প্রার্থনার জন্য নবী ﷺ এটি শিখিয়েছেন।`, fas: `پیش از ورود به دستشویی و اگر در فضای باز است پیش از درآوردن لباس، در دل خوانده می‌شود. پیامبر ﷺ این را برای پناه‌جستن به خدا از جنّیانِ پلیدی که در چنین جاهایی رفت‌وآمد می‌کنند آموخت.`, zh: `入厕前默念之，若在旷野则于脱衣前默念。先知 ﷺ 教之，以求真主护佑，免受出没此处之污秽魔灵所害。`, yue: `入廁前默念之，若在曠野則於脫衣前默念。先知 ﷺ 教之，以求真主護佑，免受出沒此處之污穢魔靈所害。`, ja: `トイレに入る前、開けた場所であれば衣服を脱ぐ前に、心の中で唱えます。預言者 ﷺ は、そのような場所に出没する汚れたジンからのアッラーの守りを求めてこれを教えられました。`, ru: `Читается про себя перед входом в туалет, а в открытом месте, перед снятием одежды. Пророк ﷺ научил этому ради прибегания к Аллаху от нечистых джиннов, часто посещающих такие места.`, es: `Se dice en silencio antes de entrar al retrete, o antes de quitarse la ropa si se está en un lugar abierto. El Profeta ﷺ lo enseñó para pedir la protección de Al-lah frente a los yinn impuros que frecuentan estos sitios.`, ko: `화장실에 들어가기 전, 혹은 야외라면 옷을 벗기 전에 조용히 낭송한다. 예언자 ﷺ 께서는 그러한 장소에 자주 나타나는 부정한 진들로부터 알라의 보호를 구하도록 이를 가르치셨다.`, ta: `கழிப்பறையில் நுழைவதற்கு முன், அல்லது திறந்த வெளியில் இருந்தால் ஆடையை அகற்றுவதற்கு முன், மௌனமாக ஓதப்படுகிறது. இத்தகைய இடங்களில் அடிக்கடி வரும் அசுத்த ஜின்களிலிருந்து அல்லாஹ்வின் பாதுகாப்பைத் தேட நபி ﷺ இதைக் கற்பித்தார்.`, si: `වැසිකිළියට ඇතුළු වීමට පෙර, විවෘත ස්ථානයක නම් ඇඳුම් ගැලවීමට පෙර, නිහඬව මෙය කියවේ. එවැනි ස්ථානවලට නිතර පැමිණෙන අශුද්ධ ජින්නයන්ගෙන් අල්ලාහ්ගේ රැකවරණය පැතීමට නබි ﷺ තුමා මෙය උගැන්වීය.` },
  dua_enter_source: { en: `Source: al-Bukhari 142, Muslim 375 (Anas ibn Malik).`, ms: `Sumber: al-Bukhari 142, Muslim 375 (Anas ibn Malik).`, tur: `Kaynak: Buhârî 142, Müslim 375 (Enes ibn Mâlik).`, urd: `ماخذ: بخاری ۱۴۲، مسلم ۳۷۵ (انس بن مالک)۔`, ben: `উৎস: বুখারি ১৪২, মুসলিম ৩৭৫ (আনাস ইবন মালিক)।`, fas: `منبع: بخاری ۱۴۲، مسلم ۳۷۵ (انس بن مالک).`, zh: `出处：布哈里 142、穆斯林 375（艾奈斯·本·马立克）。`, yue: `出處：布哈里 142、穆斯林 375（艾奈斯·本·馬立克）。`, ja: `出典：ブハーリー 142、ムスリム 375（アナス・イブン・マーリク）。`, ru: `Источник: аль-Бухари 142, Муслим 375 (Анас ибн Малик).`, es: `Fuente: al-Bukhari 142, Muslim 375 (Anas ibn Malik).`, ko: `출처: 알부카리 142, 무슬림 375 (아나스 이븐 말리크).`, ta: `மூலம்: புகாரி 142, முஸ்லிம் 375 (அனஸ் இப்னு மாலிக்).`, si: `මූලාශ්‍රය: බුකාරි 142, මුස්ලිම් 375 (අනස් ඉබ්න් මාලික්).` },

  dua_exit_h: { en: `The Du'a After Leaving`, ms: `Doa Selepas Keluar`, tur: `Çıkıştan Sonraki Duâ`, urd: `نکلنے کے بعد کی دعا`, ben: `বেরিয়ে আসার পরের দোয়া`, fas: `دعای پس از خروج`, zh: `出后之祷`, yue: `出後之禱`, ja: `出た後の祈願`, ru: `Дуа после выхода`, es: `La Du'a al salir`, ko: `나온 후의 두아`, ta: `வெளியேறியபின் பிரார்த்தனை`, si: `පිටව යාමෙන් පසු දුආව` },
  dua_exit_translit: { en: `Ghufranaka.`, ms: `Ghufranaka.`, tur: `Ğufrâneke.`, urd: `غُفْرَانَكَ۔`, ben: `গুফরানাকা।`, fas: `غفرانک.`, zh: `乌夫拉纳卡。`, yue: `烏夫拉納卡。`, ja: `グフラーナカ。`, ru: `Гуфранака.`, es: `Ghufranaka.`, ko: `구프라나카.`, ta: `குஃப்ரானக்க.`, si: `ගුෆ්‍රානක.` },
  dua_exit_meaning: { en: `(I ask) Your forgiveness.`, ms: `(Aku memohon) keampunan-Mu.`, tur: `(Senin) bağışlamanı (dilerim).`, urd: `(میں طلب کرتا ہوں) تیری بخشش۔`, ben: `(আমি চাই) আপনার ক্ষমা।`, fas: `(از تو می‌خواهم) آمرزش تو را.`, zh: `（我求）你的赦宥。`, yue: `（我求）你嘅赦宥。`, ja: `（われは求む）御身の御赦しを。`, ru: `(Прошу) Твоего прощения.`, es: `(Pido) Tu perdón.`, ko: `(저는 구합니다) 당신의 용서를.`, ta: `(உன்னிடம் கேட்கிறேன்) உன் மன்னிப்பை.`, si: `(ඉල්ලමි) ඔබේ සමාව.` },
  dua_exit_p: { en: `A brief admission that even in relieving the body of impurity, the servant is dependent on Allah's pardon. 'Aisha (ra) said this was the Prophet's ﷺ habit whenever he left the toilet.`, ms: `Pengakuan singkat bahawa walaupun ketika membersihkan tubuh daripada kekotoran, hamba tetap bergantung kepada keampunan Allah. 'Aisyah (ra) berkata inilah kebiasaan Nabi ﷺ setiap kali keluar dari tandas.`, tur: `Bedeni pislikten temizlerken bile kulun Allah'ın bağışına muhtaç olduğunun kısa bir itirafıdır. Hz. Âişe (r.a.) Peygamber'in ﷺ tuvaletten her çıkışında bunu okuduğunu bildirir.`, urd: `ایک مختصر اعتراف کہ جسم کو نجاست سے پاک کرتے ہوئے بھی بندہ اللہ کی مغفرت کا محتاج ہے۔ عائشہ (رض) نے فرمایا کہ نبی ﷺ کی عادت تھی کہ جب بھی بیت الخلا سے نکلتے تو یہی پڑھتے۔`, ben: `শরীরকে অপবিত্রতা থেকে পরিষ্কার করার সময়ও বান্দা যে আল্লাহর ক্ষমার মুখাপেক্ষী তার সংক্ষিপ্ত স্বীকৃতি। আয়িশা (রা) বলেছেন এটি ছিল নবী ﷺ-এর অভ্যাস যখনই তিনি শৌচাগার থেকে বের হতেন।`, fas: `اعتراف کوتاهی به اینکه بنده حتی هنگام پاک‌کردن بدن از پلیدی نیز به آمرزش خدا نیازمند است. عایشه (رض) گفت این عادت پیامبر ﷺ بود هرگاه از دستشویی بیرون می‌آمد.`, zh: `简短之陈白：即使涤除身体污秽之时，仆人仍需真主之赦宥。阿伊莎（愿主喜之）云：先知 ﷺ 每出厕，必诵此语。`, yue: `簡短之陳白：即使滌除身體污穢之時，僕人仍需真主之赦宥。阿伊莎（願主喜之）云：先知 ﷺ 每出廁，必誦此語。`, ja: `身体を汚れから清めるときにさえ、僕はアッラーの御赦しに依らねばならぬという短い告白です。アーイシャ（ラ）は、預言者 ﷺ が厠を出るたびにこれを唱えられたのが習わしであったと伝えます。`, ru: `Краткое признание того, что даже очищая тело от нечистоты, раб нуждается в прощении Аллаха. 'Аиша (ра) сообщает, что таков был обычай Пророка ﷺ всякий раз, когда он выходил из отхожего места.`, es: `Un breve reconocimiento de que, incluso al aliviar el cuerpo de la impureza, el siervo depende del perdón de Al-lah. 'Aisha (ra) dijo que ésa era la costumbre del Profeta ﷺ cada vez que salía del retrete.`, ko: `몸을 부정에서 씻어내는 순간에도 종은 알라의 용서에 의지한다는 짧은 고백이다. 아이샤(라)께서는 예언자 ﷺ 께서 화장실을 나오실 때마다 이를 낭송하시는 것이 습관이었다고 전하셨다.`, ta: `உடலைத் தூய்மையாக்கும் தருணத்திலும்கூட அடியான் அல்லாஹ்வின் மன்னிப்புக்கு தேவைப்படுகிறான் என்பதற்கான சுருக்கமான ஒப்புதல். ஆயிஷா (ரலி) கூறினார்: நபி ﷺ கழிப்பறையிலிருந்து வெளியேறும் ஒவ்வொரு முறையும் இதையே சொல்வதே அவரது வழக்கம்.`, si: `අශුද්ධතාවෙන් ශරීරය පිරිසිදු කරන අවස්ථාවේ පවා දේවසේවකයා අල්ලාහ්ගේ සමාවට යැපෙන බවට කෙටි පිළිගැනීමකි. නබි ﷺ තුමා වැසිකිළියෙන් පිටව යන සෑම විටම මෙය කීම ඔහුගේ පුරුද්ද යැයි ආඉෂා (රළි) පැවසූහ.` },
  dua_exit_source: { en: `Source: Abu Dawud 30, al-Tirmidhi 7, Ibn Majah 300, graded sahih by al-Albani.`, ms: `Sumber: Abu Dawud 30, al-Tirmidhi 7, Ibn Majah 300, dinilai sahih oleh al-Albani.`, tur: `Kaynak: Ebû Dâvud 30, Tirmizî 7, İbn Mâce 300; Elbânî sahih dedi.`, urd: `ماخذ: ابو داود ۳۰، ترمذی ۷، ابن ماجہ ۳۰۰؛ البانی نے صحیح قرار دیا۔`, ben: `উৎস: আবু দাউদ ৩০, তিরমিযি ৭, ইবন মাজাহ ৩০০; আল-বানি সহীহ বলেছেন।`, fas: `منبع: ابوداود ۳۰، ترمذی ۷، ابن ماجه ۳۰۰؛ آلبانی صحیح دانسته است.`, zh: `出处：艾布·达乌德 30、提尔米济 7、伊本·马哲 300；艾布尼判为正传。`, yue: `出處：艾布·達烏德 30、提爾米濟 7、伊本·馬哲 300；艾布尼判為正傳。`, ja: `出典：アブー・ダーウード 30、ティルミズィー 7、イブン・マージャ 300；アルバーニーが正伝と評した。`, ru: `Источник: Абу Дауд 30, ат-Тирмизи 7, Ибн Маджа 300; аль-Албани оценил как сахих.`, es: `Fuente: Abu Dawud 30, al-Tirmidhi 7, Ibn Maja 300; al-Albani lo calificó de sahih.`, ko: `출처: 아부 다우드 30, 알티르미디 7, 이븐 마자 300; 알알바니가 사히흐로 평가.`, ta: `மூலம்: அபூ தாவூத் 30, திர்மிதி 7, இப்னு மாஜா 300; அல்-அல்பானி ஸஹீஹ் என்று தரப்படுத்தினார்.`, si: `මූලාශ්‍රය: අබූ දාවූද් 30, තිර්මිදි 7, ඉබ්න් මාජා 300; අල්-අල්බානි සහීහ් ලෙස තක්සේරු කළහ.` },

  foot_h: { en: `Which Foot to Enter and Leave With`, ms: `Dengan Kaki Mana Masuk dan Keluar`, tur: `Hangi Ayakla Girilir ve Çıkılır`, urd: `کس پاؤں سے داخل ہوں اور کس سے نکلیں`, ben: `কোন পা দিয়ে ঢুকবেন এবং বের হবেন`, fas: `با کدام پا وارد و خارج شویم`, zh: `以何足入以何足出`, yue: `以何足入以何足出`, ja: `どちらの足で入り、どちらで出るか`, ru: `Какой ногой входить и выходить`, es: `Con qué pie entrar y salir`, ko: `어느 발로 들어가고 나오는가`, ta: `எந்த காலால் நுழைவது வெளியேறுவது`, si: `කුමන පාදයෙන් ඇතුළු වී පිටව යා යුතුද` },
  foot_p1: { en: `Enter with the left foot. Leave with the right foot. The general principle from the Sunnah is that the right hand and foot are used for what is honourable (eating, entering the mosque, putting on clothes), and the left is used for what is not (cleansing after the toilet, removing shoes).`, ms: `Masuk dengan kaki kiri. Keluar dengan kaki kanan. Prinsip umum daripada Sunnah ialah tangan dan kaki kanan digunakan untuk perkara yang mulia (makan, masuk ke masjid, memakai pakaian), dan tangan serta kaki kiri digunakan untuk perkara yang sebaliknya (bersuci selepas buang air, menanggalkan kasut).`, tur: `Sol ayakla girilir. Sağ ayakla çıkılır. Sünnetin umum prensibi şudur: sağ el ve sağ ayak şerefli işler için (yemek yeme, mescide girme, giyinme) kullanılır; sol ise şerefli olmayan işler için (tuvaletten sonra temizlenme, ayakkabı çıkarma) kullanılır.`, urd: `بائیں پاؤں سے داخل ہوں۔ دائیں پاؤں سے نکلیں۔ سنت کا عمومی اصول یہ ہے کہ دایاں ہاتھ اور پاؤں معزز کاموں کے لیے استعمال ہوتا ہے (کھانا کھانا، مسجد میں داخل ہونا، لباس پہننا)، اور بایاں ان کاموں کے لیے جو معزز نہیں (بیت الخلا کے بعد صفائی، جوتے اتارنا)۔`, ben: `বাম পা দিয়ে প্রবেশ করুন। ডান পা দিয়ে বের হন। সুন্নাহর সাধারণ নীতি হলো ডান হাত ও ডান পা সম্মানজনক কাজে ব্যবহৃত হয় (খাওয়া, মসজিদে প্রবেশ, পোশাক পরা), এবং বাম হাত-পা সম্মানজনক নয় এমন কাজে (শৌচাগারের পর পরিচ্ছন্নতা, জুতা খোলা)।`, fas: `با پای چپ وارد شوید. با پای راست خارج شوید. اصل کلی سنت این است که دست و پای راست برای کارهای شرافتمندانه (خوردن، ورود به مسجد، پوشیدن لباس) به کار می‌رود و چپ برای آنچه چنین نیست (طهارت پس از دستشویی، درآوردن کفش).`, zh: `以左足入，以右足出。圣行之通则：右手右足用于尊贵之事（进食、入寺、着衣），左手左足用于其反（如厕后之洁净、脱鞋）。`, yue: `以左足入，以右足出。聖行之通則：右手右足用於尊貴之事（進食、入寺、著衣），左手左足用於其反（如廁後之潔淨、脫鞋）。`, ja: `左足で入り、右足で出ます。スンナの一般原則は、右手・右足は尊いこと（食事、モスクへの入場、衣服の着用）に用い、左は尊くないこと（用便後の清め、履物を脱ぐこと）に用いるというものです。`, ru: `Входите с левой ноги. Выходите с правой. Общий принцип Сунны: правая рука и правая нога используются для благородного (еды, входа в мечеть, одевания), а левая, для противоположного (очищения после туалета, снятия обуви).`, es: `Entrar con el pie izquierdo. Salir con el pie derecho. El principio general de la Sunna: la mano y el pie derechos se usan para lo honorable (comer, entrar a la mezquita, vestirse), y los izquierdos para lo que no lo es (limpiarse tras el retrete, quitarse el calzado).`, ko: `왼발로 들어가고 오른발로 나온다. 순나의 일반 원칙: 오른손과 오른발은 명예로운 일에(식사, 모스크 입장, 옷 입기), 왼쪽은 그렇지 않은 일에(용변 후 세정, 신발 벗기) 사용한다.`, ta: `இடது காலால் நுழையுங்கள். வலது காலால் வெளியேறுங்கள். ஸுன்னாவின் பொது கொள்கை: வலது கை மற்றும் வலது கால் மரியாதைக்குரிய செயல்களுக்குப் (உண்பது, மசூதிக்குள் நுழைவது, ஆடை அணிவது) பயன்படுத்தப்படுகிறது; இடது அல்லாத செயல்களுக்குப் (கழிப்பறைக்குப் பின் தூய்மைப்படுத்துதல், காலணி கழற்றுதல்) பயன்படுத்தப்படுகிறது.`, si: `වම් පාදයෙන් ඇතුළු වන්න. දකුණු පාදයෙන් පිටව යන්න. සුන්නාවේ පොදු මූලධර්මය: දකුණු අත සහ දකුණු පාදය ගෞරවනීය කටයුතුවලට (ආහාර ගැනීම, මස්ජිදට ඇතුළු වීම, ඇඳුම් ඇඳීම) යොදන අතර, වම එසේ නොවන දේවලට (වැසිකිළියෙන් පසු පිරිසිදු කිරීම, පාවහන් ගැලවීම) යොදනු ලැබේ.` },
  foot_p2: { en: `'Aisha (ra) said: "The Prophet ﷺ used to like to begin with the right in his purification, in combing his hair, and in putting on his shoes."`, ms: `'Aisyah (ra) berkata: "Nabi ﷺ suka memulakan dengan sebelah kanan dalam bersuci, menyisir rambut, dan memakai kasut."`, tur: `Hz. Âişe (r.a.) buyurdu: "Peygamber ﷺ, temizliğinde, saçını tararken ve ayakkabısını giyerken sağdan başlamayı severdi."`, urd: `عائشہ (رض) نے فرمایا: "نبی ﷺ کو پاکی حاصل کرنے، بال سنوارنے اور جوتا پہننے میں دائیں طرف سے شروع کرنا پسند تھا۔"`, ben: `আয়িশা (রা) বলেন: "নবী ﷺ তাঁর পবিত্রতা অর্জনে, চুল আঁচড়ানোয় ও জুতা পরায় ডান দিক থেকে শুরু করা পছন্দ করতেন।"`, fas: `عایشه (رض) گفت: «پیامبر ﷺ دوست می‌داشت در پاکیزگی، شانه‌کردن مو و پوشیدن کفش از سمت راست آغاز کند.»`, zh: `阿伊莎（愿主喜之）云：「先知 ﷺ 喜爱在净礼、梳发与穿鞋时自右侧起。」`, yue: `阿伊莎（願主喜之）云：「先知 ﷺ 喜愛在淨禮、梳髮與穿鞋時自右側起。」`, ja: `アーイシャ（ラ）は言われた。「預言者 ﷺ は、清めにおいても、髪を梳かすにおいても、履物を履くにおいても、右から始めることを好まれた。」`, ru: `'Аиша (ра) сказала: «Пророк ﷺ любил начинать с правой стороны в очищении, при расчёсывании волос и при обувании».`, es: `'Aisha (ra) dijo: «Al Profeta ﷺ le gustaba comenzar por el lado derecho en su purificación, al peinarse el cabello y al calzarse.»`, ko: `아이샤(라)께서 말씀하시길: "예언자 ﷺ 께서는 정결례에서, 머리를 빗을 때, 신발을 신을 때 오른쪽부터 시작하는 것을 좋아하셨다."`, ta: `ஆயிஷா (ரலி) கூறினார்: "தூய்மை பெறுவதிலும், தலைமுடி வாரிக்கொள்வதிலும், காலணி அணிவதிலும் நபி ﷺ வலப்பக்கத்திலிருந்து தொடங்குவதை விரும்பினார்."`, si: `ආඉෂා (රළි) පැවසුවාය: "පිරිසිදු කිරීමේදී, කේශ පෙති සකස් කිරීමේදී සහ පාවහන් ඇඳීමේදී දකුණු පැත්තෙන් ආරම්භ කිරීම නබි ﷺ තුමා ප්‍රිය කළහ."` },
  foot_source: { en: `Source: al-Bukhari 168, Muslim 268.`, ms: `Sumber: al-Bukhari 168, Muslim 268.`, tur: `Kaynak: Buhârî 168, Müslim 268.`, urd: `ماخذ: بخاری ۱۶۸، مسلم ۲۶۸۔`, ben: `উৎস: বুখারি ১৬৮, মুসলিম ২৬৮।`, fas: `منبع: بخاری ۱۶۸، مسلم ۲۶۸.`, zh: `出处：布哈里 168、穆斯林 268。`, yue: `出處：布哈里 168、穆斯林 268。`, ja: `出典：ブハーリー 168、ムスリム 268。`, ru: `Источник: аль-Бухари 168, Муслим 268.`, es: `Fuente: al-Bukhari 168, Muslim 268.`, ko: `출처: 알부카리 168, 무슬림 268.`, ta: `மூலம்: புகாரி 168, முஸ்லிம் 268.`, si: `මූලාශ්‍රය: බුකාරි 168, මුස්ලිම් 268.` },

  qibla_h: { en: `Facing the Qiblah`, ms: `Menghadap Kiblat`, tur: `Kıbleye Yönelmek`, urd: `قبلہ رخ کرنا`, ben: `কিবলামুখী হওয়া`, fas: `رو به قبله بودن`, zh: `朝向基卜莱`, yue: `朝向基卜萊`, ja: `キブラに向くこと`, ru: `Обращение к кибле`, es: `Orientarse hacia la Qiblah`, ko: `키블라를 향함`, ta: `கிப்லாவை நோக்குதல்`, si: `කිබ්ලාව දෙසට යොමු වීම` },
  qibla_translation: { en: `When you go to relieve yourselves, do not face the qiblah nor turn your backs to it while urinating or defecating, but face east or west (in the Prophet's ﷺ Madinan context).`, ms: `Apabila kamu pergi membuang air, jangan menghadap kiblat mahupun membelakanginya semasa membuang air kecil atau besar, tetapi hadapkan diri ke timur atau ke barat (dalam konteks Madinah Nabi ﷺ).`, tur: `Def-i hâcete gittiğinizde, küçük veya büyük abdest bozarken ne kıbleye dönün ne de sırtınızı ona çevirin; doğuya veya batıya dönün (Peygamber'in ﷺ Medine bağlamında).`, urd: `جب تم قضائے حاجت کے لیے جاؤ تو پیشاب یا پاخانہ کرتے وقت نہ قبلہ کی طرف رخ کرو اور نہ اسے پیٹھ کرو، بلکہ مشرق یا مغرب کی طرف رخ کرو (نبی ﷺ کے مدینہ کے تناظر میں)۔`, ben: `যখন তোমরা প্রস্রাব-পায়খানার জন্য যাও, প্রস্রাব বা পায়খানার সময় কিবলামুখী হয়ো না এবং কিবলাকে পিছনে করেও রেখো না, বরং পূর্ব বা পশ্চিমমুখী হও (নবী ﷺ-এর মদিনার প্রেক্ষাপটে)।`, fas: `چون برای قضای حاجت می‌روید، هنگام پیشاب یا مدفوع نه رو به قبله باشید و نه پشت به قبله؛ بلکه به سوی مشرق یا مغرب بنشینید (در بستر مدینهٔ پیامبر ﷺ).`, zh: `汝等如厕之时，勿面基卜莱亦勿背之，当面东或面西（此在先知 ﷺ 之麦地那语境）。`, yue: `汝等如廁之時，勿面基卜萊亦勿背之，當面東或面西（此在先知 ﷺ 之麥地那語境）。`, ja: `用便に立つときは、大小のいずれにおいてもキブラに向かってはならず、背を向けてもならぬ。東または西を向きなさい（預言者 ﷺ のマディーナの文脈で）。`, ru: `Когда идёте отправлять нужду, не обращайтесь лицом к кибле и не поворачивайтесь к ней спиной во время малой или большой нужды, а обращайтесь на восток или на запад (в мадинском контексте Пророка ﷺ).`, es: `Cuando vayáis a hacer vuestras necesidades, no os pongáis frente a la qiblah ni le deis la espalda al orinar o defecar, sino orientaos hacia el este o el oeste (en el contexto medinense del Profeta ﷺ).`, ko: `너희가 용변을 보러 갈 때, 대소변을 볼 동안 키블라를 향하지도 등지지도 말고 동쪽이나 서쪽을 향하라 (예언자 ﷺ 의 마디나 맥락에서).`, ta: `நீங்கள் இயற்கை உபாதைக்குச் செல்லும்போது, சிறுநீர் அல்லது மலம் கழிக்கும் நேரத்தில் கிப்லாவை நோக்கியோ அல்லது அதற்கு முதுகு காட்டியோ இருக்க வேண்டாம்; கிழக்கு அல்லது மேற்கு நோக்கி இருங்கள் (நபி ﷺ காலத்திய மதீனா சூழலில்).`, si: `අවශ්‍යතාව සඳහා යන විට, මුත්‍රා හෝ මළ බැහැර කරන අවස්ථාවේදී කිබ්ලාව දෙසට මුහුණ ලා හෝ පිට හරවා නොසිටින්න; නමුත් නැගෙනහිර හෝ බස්නාහිර දෙසට හැරෙන්න (නබි ﷺ තුමන්ගේ මදීනා සන්දර්භය තුළ).` },
  qibla_p: { en: `In the open (a desert, an unwalled field), one must neither face nor turn one's back to the Ka'bah while relieving oneself. Inside a built toilet, the majority of scholars (Hanafi, Shafi'i, Hanbali) permit it out of necessity because a wall now stands between the person and the qiblah. Malikis hold to the stricter view even indoors. When you can, orient the toilet away from the qiblah.`, ms: `Di tempat terbuka (padang pasir, ladang yang tidak berdinding), seseorang tidak boleh menghadap Ka'bah atau membelakanginya semasa membuang air. Di dalam tandas berbina, majoriti ulama (Hanafi, Syafi'i, Hanbali) membenarkannya kerana keperluan, kerana kini ada dinding antara orang itu dengan kiblat. Ulama Maliki berpegang pada pandangan yang lebih ketat walaupun di dalam bangunan. Apabila boleh, hadapkan tandas jauh daripada kiblat.`, tur: `Açıkta (çölde, duvarsız bir arazide) def-i hâcet ederken Kâbe'ye ne dönülür ne de sırt çevrilir. Kapalı bir tuvalette çoğu âlim (Hanefî, Şâfiî, Hanbelî), aradaki duvar sebebiyle zaruret gereği izin verir. Mâlikîler ise kapalı yerde bile daha katı görüşü benimser. Mümkün olduğunda tuvaleti kıbleden uzak yönlendirin.`, urd: `کھلی جگہ (صحرا، بغیر دیوار کے میدان) میں قضائے حاجت کرتے وقت کعبہ کی طرف رخ کرنا یا پیٹھ کرنا جائز نہیں۔ بند بیت الخلا میں اکثر علماء (حنفی، شافعی، حنبلی) ضرورت کے سبب اسے جائز کہتے ہیں کیونکہ اب بندے اور قبلہ کے درمیان دیوار حائل ہے۔ مالکی حضرات اندر بھی سخت رائے پر قائم ہیں۔ جہاں ممکن ہو، بیت الخلا کا رخ قبلہ سے دور رکھیں۔`, ben: `খোলা জায়গায় (মরুভূমি, দেয়ালহীন মাঠ) প্রস্রাব-পায়খানা করার সময় কা'বার দিকে মুখ বা পিঠ ফেরানো যাবে না। বদ্ধ শৌচাগারের ভেতরে অধিকাংশ আলিম (হানাফি, শাফিয়ি, হানবলি) প্রয়োজনবশত এটি অনুমোদন করেন, কারণ এখন ব্যক্তি ও কিবলার মাঝে দেয়াল দাঁড়িয়ে আছে। মালিকিরা ভেতরেও কঠোর অভিমত পোষণ করেন। যখন সম্ভব, শৌচাগারকে কিবলা থেকে সরিয়ে দিক নির্দেশ করুন।`, fas: `در فضای باز (بیابان، دشتِ بی‌دیوار) هنگام قضای حاجت نه رو به کعبه باشید و نه پشت به آن. در دستشویی سرپوشیده، جمهور علما (حنفی، شافعی، حنبلی) به دلیل ضرورت آن را جایز می‌دانند، زیرا اکنون دیواری میان شخص و قبله وجود دارد. مالکیان حتی درون بنا نیز نظر سخت‌گیرانه‌تری دارند. تا آنجا که ممکن است، جهت دستشویی را از قبله برگردانید.`, zh: `旷野之中（沙漠、无墙之地）如厕之时，不可面卡巴亦不可背之。若在有墙之厕内，教法学者多数（哈奈斐、沙菲仪、罕百里）以必要为由允许之，因人与基卜莱之间已有墙相隔。马立克派虽在墙内仍持严说。凡能则应将厕所朝向偏离基卜莱。`, yue: `曠野之中（沙漠、無牆之地）如廁之時，不可面卡巴亦不可背之。若在有牆之廁內，教法學者多數（哈奈斐、沙菲儀、罕百里）以必要為由允許之，因人與基卜萊之間已有牆相隔。馬立克派雖在牆內仍持嚴說。凡能則應將廁所朝向偏離基卜萊。`, ja: `野外（砂漠、囲いのない野原）で用便を足すときは、カアバに向かっても背を向けてもならぬ。囲われた便所の中では、多数の学者（ハナフィー、シャーフィイー、ハンバリー）は間に壁があるため必要により許す。マーリキーは屋内でもより厳格な見解を採る。可能なら便所の向きをキブラから外して設けよ。`, ru: `На открытом месте (в пустыне, в поле без стен) при отправлении нужды нельзя ни обращаться лицом к Каабе, ни поворачиваться к ней спиной. Внутри построенного туалета большинство учёных (ханафиты, шафииты, ханбалиты) разрешают это по необходимости, поскольку между человеком и киблой теперь стена. Маликиты придерживаются более строгого мнения даже в помещении. Когда возможно, ориентируйте туалет в сторону от киблы.`, es: `A cielo abierto (un desierto, un campo sin muros) no se debe estar de cara a la Ka'ba ni de espaldas al hacer las necesidades. Dentro de un retrete construido, la mayoría de los sabios (hanafíes, shafi'íes, hanbalíes) lo permiten por necesidad, ya que hay un muro entre la persona y la qiblah. Los malikíes mantienen la opinión más estricta incluso en interiores. Cuando sea posible, orienta el retrete lejos de la qiblah.`, ko: `야외(사막이나 벽 없는 들판)에서 용변을 볼 때 카아바를 향하거나 등져서는 안 된다. 벽으로 둘러싸인 화장실 안에서는 다수 학파(하나피, 샤피이, 한발리)가 사람과 키블라 사이에 벽이 있으므로 필요에 따라 허용한다. 말리키는 실내에서도 더 엄격한 견해를 유지한다. 가능하면 화장실 방향을 키블라와 어긋나게 설치하라.`, ta: `திறந்த வெளியில் (பாலைவனம், சுவரற்ற வயல்) இயற்கை உபாதைக்குச் செல்லும்போது கஅபாவை நோக்கியோ அதற்கு முதுகு காட்டியோ இருக்கக்கூடாது. கட்டப்பட்ட கழிப்பறையினுள், அறிஞர்களில் பெரும்பாலோர் (ஹனஃபி, ஷாஃபி, ஹன்பலி) அவசியத்தால் இதனை அனுமதிக்கின்றனர், ஏனெனில் இப்போது நபருக்கும் கிப்லாவுக்கும் இடையே சுவர் நிற்கிறது. மாலிக்கிகள் உள்ளேயும் கடுமையான கருத்தையே கடைப்பிடிக்கின்றனர். இயலுமானபோது, கழிப்பறையின் திசையை கிப்லாவிலிருந்து விலகி அமைக்கவும்.`, si: `විවෘත ස්ථානයේ (කාන්තාරය, බැම්මක් නොමැති කෙතක්) අවශ්‍යතාව සිදු කරන විට කඃබාවට මුහුණ ලා හෝ පිට හරවා නොසිටිය යුතුය. බැඳුණු වැසිකිළියක් තුළ, බහුතර විද්වත්හු (හනෆි, ෂාෆිඊ, හන්බලි) ඉතා අවශ්‍යතාව අනුව අවසර දෙති, මන්ද දැන් පුද්ගලයා සහ කිබ්ලාව අතර බැම්මක් පවතී. මාලිකි විද්වත්හු ගෘහ ඇතුළත වුවද වඩාත් තදකම දිගටම ගෙන යති. හැකි විටෙක, වැසිකිළියේ දිශාව කිබ්ලාවෙන් ඉවතට යොමු කරන්න.` },
  qibla_source: { en: `Source: al-Bukhari 394, Muslim 264 (Abu Ayyub al-Ansari).`, ms: `Sumber: al-Bukhari 394, Muslim 264 (Abu Ayyub al-Ansari).`, tur: `Kaynak: Buhârî 394, Müslim 264 (Ebû Eyyûb el-Ensârî).`, urd: `ماخذ: بخاری ۳۹۴، مسلم ۲۶۴ (ابو ایوب الانصاری)۔`, ben: `উৎস: বুখারি ৩৯৪, মুসলিম ২৬৪ (আবু আইয়ুব আল-আনসারি)।`, fas: `منبع: بخاری ۳۹۴، مسلم ۲۶۴ (ابوایوب انصاری).`, zh: `出处：布哈里 394、穆斯林 264（艾布·艾优卜·安萨里）。`, yue: `出處：布哈里 394、穆斯林 264（艾布·艾優卜·安薩里）。`, ja: `出典：ブハーリー 394、ムスリム 264（アブー・アイユーブ・アル＝アンサーリー）。`, ru: `Источник: аль-Бухари 394, Муслим 264 (Абу Айюб аль-Ансари).`, es: `Fuente: al-Bukhari 394, Muslim 264 (Abu Ayyub al-Ansari).`, ko: `출처: 알부카리 394, 무슬림 264 (아부 아이유브 알안사리).`, ta: `மூலம்: புகாரி 394, முஸ்லிம் 264 (அபூ அய்யூப் அல்-அன்சாரி).`, si: `මූලාශ්‍රය: බුකාරි 394, මුස්ලිම් 264 (අබූ අය්යූබ් අල්-අන්සාරි).` },

  forbidden_h: { en: `Places Where Relieving Oneself Is Forbidden`, ms: `Tempat-tempat yang Dilarang Membuang Air`, tur: `Def-i Hâcetin Yasak Olduğu Yerler`, urd: `وہ مقامات جہاں قضائے حاجت منع ہے`, ben: `যেসব স্থানে প্রস্রাব-পায়খানা নিষিদ্ধ`, fas: `مکان‌هایی که قضای حاجت در آنها ممنوع است`, zh: `禁于何处如厕`, yue: `禁於何處如廁`, ja: `用便が禁じられる場所`, ru: `Места, где отправление нужды запрещено`, es: `Lugares donde está prohibido hacer las necesidades`, ko: `용변이 금지된 장소`, ta: `இயற்கை உபாதை தடைசெய்யப்பட்ட இடங்கள்`, si: `අවශ්‍යතාව සිදු කිරීම තහනම් ස්ථාන` },
  forbidden_intro: { en: `The Prophet ﷺ forbade relieving oneself in:`, ms: `Nabi ﷺ melarang membuang air di:`, tur: `Peygamber ﷺ şu yerlerde def-i hâceti yasakladı:`, urd: `نبی ﷺ نے ان جگہوں پر قضائے حاجت سے منع فرمایا:`, ben: `নবী ﷺ যেসব স্থানে প্রস্রাব-পায়খানা নিষেধ করেছেন:`, fas: `پیامبر ﷺ از قضای حاجت در این مکان‌ها نهی فرمود:`, zh: `先知 ﷺ 禁人如厕于以下处：`, yue: `先知 ﷺ 禁人如廁於以下處：`, ja: `預言者 ﷺ は次の場所での用便を禁じられた：`, ru: `Пророк ﷺ запретил отправлять нужду в:`, es: `El Profeta ﷺ prohibió hacer las necesidades en:`, ko: `예언자 ﷺ 께서는 다음의 장소에서 용변을 금하셨다:`, ta: `நபி ﷺ இந்த இடங்களில் இயற்கை உபாதையை தடை செய்தார்:`, si: `නබි ﷺ තුමා පහත ස්ථානවල අවශ්‍යතාව සිදු කිරීම තහනම් කළහ:` },
  forbidden_1: { en: `Stagnant water that others may use (Muslim 281, Jabir).`, ms: `Air bertakung yang mungkin digunakan orang lain (Muslim 281, Jabir).`, tur: `Başkalarının kullanabileceği durgun sular (Müslim 281, Câbir).`, urd: `رکا ہوا پانی جسے دوسرے استعمال کر سکتے ہوں (مسلم ۲۸۱، جابر)۔`, ben: `স্থির পানি যা অন্যরা ব্যবহার করতে পারে (মুসলিম ২৮১, জাবির)।`, fas: `آب راکد که دیگران ممکن است از آن استفاده کنند (مسلم ۲۸۱، جابر).`, zh: `静止之水，人可用之者（穆斯林 281，贾比尔）。`, yue: `靜止之水，人可用之者（穆斯林 281，賈比爾）。`, ja: `他の人が使う恐れのある淀んだ水（ムスリム 281、ジャービル）。`, ru: `Стоячая вода, которую могут использовать другие (Муслим 281, Джабир).`, es: `Agua estancada que otros puedan usar (Muslim 281, Yabir).`, ko: `다른 이가 사용할 수 있는 고인 물 (무슬림 281, 자비르).`, ta: `மற்றவர்கள் பயன்படுத்தக்கூடிய தேங்கிய நீர் (முஸ்லிம் 281, ஜாபிர்).`, si: `අන් අය භාවිතා කළ හැකි නිශ්චල ජලය (මුස්ලිම් 281, ජාබිර්).` },
  forbidden_2: { en: `The paths people walk and the shaded places they rest (Muslim 269, Abu Hurayra), calling these the two "cursed acts."`, ms: `Jalan yang dilalui orang dan tempat teduh tempat mereka berehat (Muslim 269, Abu Hurairah), digelar sebagai dua "perbuatan terkutuk."`, tur: `İnsanların yürüdüğü yollar ve dinlendikleri gölge yerler (Müslim 269, Ebû Hüreyre); bunları iki "lânet sebebi" olarak anmıştır.`, urd: `وہ راستے جن پر لوگ چلتے ہیں اور وہ سایہ دار جگہیں جہاں آرام کرتے ہیں (مسلم ۲۶۹، ابو ہریرہ)، انہیں دو "لعنت والے کام" فرمایا۔`, ben: `মানুষ যেসব পথে চলে এবং যেসব ছায়াময় জায়গায় বিশ্রাম নেয় (মুসলিম ২৬৯, আবু হুরায়রা), এদুটিকে "অভিশপ্ত কাজ" বলে অভিহিত করেছেন।`, fas: `راه‌هایی که مردم می‌روند و مکان‌های سایه‌دار که در آن می‌آسایند (مسلم ۲۶۹، ابوهریره)؛ این دو را «کارِ ملعون» نامید.`, zh: `人所行之路与人所憩之荫地（穆斯林 269，艾布·胡赖赖），先知称此二者为「招诅之行」。`, yue: `人所行之路與人所憩之蔭地（穆斯林 269，艾布·胡賴賴），先知稱此二者為「招詛之行」。`, ja: `人々の通る道と、人々が憩う日陰の場所（ムスリム 269、アブー・フライラ）。この二つを「呪詛を招く行い」と称された。`, ru: `Пути, по которым ходят люди, и тенистые места, где они отдыхают (Муслим 269, Абу Хурайра), назвав их двумя "проклятыми делами".`, es: `Los caminos por los que anda la gente y los lugares sombreados donde descansan (Muslim 269, Abu Hurayra); los llamó los dos "actos malditos".`, ko: `사람들이 다니는 길과 그늘 아래 쉬는 자리 (무슬림 269, 아부 후라이라); 이 둘을 두 가지 "저주받은 행위"라 부르셨다.`, ta: `மக்கள் நடக்கும் பாதைகள் மற்றும் அவர்கள் ஓய்வெடுக்கும் நிழலான இடங்கள் (முஸ்லிம் 269, அபூ ஹுரைரா), இவை இரண்டையும் "சாபத்திற்குரிய செயல்கள்" என்று அழைத்தார்.`, si: `මිනිසුන් ගමන් කරන මාර්ග සහ ඔවුන් විවේක ගන්නා සෙවන ස්ථාන (මුස්ලිම් 269, අබූ හුරෛරා); මේ දෙක "ශාපිත ක්‍රියා දෙක" ලෙස හඳුන්වා දුන්හ.` },
  forbidden_3: { en: `Under fruit-bearing trees people gather from.`, ms: `Di bawah pohon berbuah yang menjadi tempat orang mengutip buahnya.`, tur: `İnsanların meyve topladığı meyveli ağaçların altında.`, urd: `پھل دار درختوں کے نیچے جن سے لوگ پھل چنتے ہیں۔`, ben: `ফলদায়ক গাছের নিচে যেসব গাছ থেকে মানুষ ফল সংগ্রহ করে।`, fas: `زیر درختان میوه‌داری که مردم از آنها میوه می‌چینند.`, zh: `众所摘食之果树之下。`, yue: `眾所摘食之果樹之下。`, ja: `人々が実を摘みに来る果樹の下。`, ru: `Под плодовыми деревьями, с которых люди собирают плоды.`, es: `Bajo árboles frutales de los que la gente recoge fruta.`, ko: `사람들이 열매를 따는 과실나무 아래.`, ta: `மக்கள் பழம் சேகரிக்கும் பழமரங்களின் கீழ்.`, si: `මිනිසුන් පල එකතු කරන ඵලදායක ගස් යට.` },
  forbidden_4: { en: `Facing the sun or moon (a preference held by many early scholars).`, ms: `Menghadap matahari atau bulan (pandangan yang dipegang oleh ramai ulama awal).`, tur: `Güneş veya aya karşı dönmek (ilk dönem âlimlerinin çoğunun tercih ettiği görüş).`, urd: `سورج یا چاند کی طرف رخ کرنا (ابتدائی علماء میں سے بہت سوں کی ترجیح)۔`, ben: `সূর্য বা চন্দ্রের দিকে মুখ করা (প্রাথমিক আলিমদের অনেকের অগ্রাধিকৃত অভিমত)।`, fas: `رو به خورشید یا ماه بودن (ترجیح بسیاری از علمای متقدم).`, zh: `面日或面月（诸多前贤所倾之意）。`, yue: `面日或面月（諸多前賢所傾之意）。`, ja: `太陽や月に向いて用便すること（初期の学者の多くが好んだ立場）。`, ru: `Обращение лицом к солнцу или к луне (мнение, которого придерживались многие ранние учёные).`, es: `Encararse al sol o a la luna (parecer que sostuvieron muchos sabios tempranos).`, ko: `해나 달을 향하는 것 (많은 초기 학자들이 선호한 견해).`, ta: `சூரியன் அல்லது சந்திரனை நோக்கியிருத்தல் (பல ஆரம்பகால அறிஞர்களின் விருப்பமான கருத்து).`, si: `හිරු හෝ සඳ දෙසට මුහුණ ලා සිටීම (බොහෝ මුල් යුගයේ විද්වතුන් අනුමත කළ මතය).` },
  forbidden_wisdom: { en: `The unifying wisdom: no act of the servant should cause disgust, harm or ritual inconvenience to another Muslim.`, ms: `Hikmah yang menyatukan: tiada perbuatan hamba yang boleh menimbulkan rasa jijik, mudarat atau kesukaran ibadah kepada Muslim yang lain.`, tur: `Birleştirici hikmet: kulun hiçbir ameli, başka bir Müslümana tiksinti, zarar veya ibadette güçlük vermemelidir.`, urd: `مشترک حکمت: بندے کا کوئی عمل کسی دوسرے مسلمان کے لیے کراہت، نقصان یا عبادت میں دقت کا سبب نہ بنے۔`, ben: `একীভূত হিকমাহ: বান্দার কোনো কাজ যেন অন্য কোনো মুসলিমের ঘৃণা, ক্ষতি বা ইবাদতের অসুবিধার কারণ না হয়।`, fas: `حکمت مشترک: هیچ عمل بنده نباید موجب کراهت، زیان یا مشقتِ عبادی مسلمان دیگری شود.`, zh: `贯通之智慧：仆人所行，皆不当致他人生厌、受害或于礼拜添难。`, yue: `貫通之智慧：僕人所行，皆不當致他人生厭、受害或於禮拜添難。`, ja: `一貫する叡智：僕のいかなる行為も、他のムスリムに嫌悪や害や礼拝上の不便をもたらしてはならない。`, ru: `Общая мудрость: ни одно действие раба не должно вызывать отвращения, причинять вред или создавать помеху в поклонении другому мусульманину.`, es: `La sabiduría común: ningún acto del siervo debe causar repugnancia, daño o dificultad ritual a otro musulmán.`, ko: `공통된 지혜: 종의 어떤 행위도 다른 무슬림에게 혐오나 해악, 예배상의 불편을 초래해서는 안 된다.`, ta: `இணையும் ஞானம்: அடியானின் எந்த செயலும் மற்றொரு முஸ்லிமுக்கு அருவருப்பையோ, தீங்கையோ, வழிபாட்டில் இடையூறையோ ஏற்படுத்தக்கூடாது.`, si: `සන්නද්ධ ප්‍රඥාව: දේවසේවකයාගේ කිසි ක්‍රියාවක් වෙනත් මුස්ලිම්වරයෙකුට පිළිකුල, හානියක් හෝ නමස්කාරයේ දුෂ්කරතාවක් ඇති නොකළ යුතුය.` },

  speech_h: { en: `Speech, the Name of Allah, and the Right Hand`, ms: `Bercakap, Nama Allah dan Tangan Kanan`, tur: `Konuşma, Allah'ın İsmi ve Sağ El`, urd: `گفتگو، اللہ کا نام اور دایاں ہاتھ`, ben: `কথাবার্তা, আল্লাহর নাম ও ডান হাত`, fas: `سخن گفتن، نام خدا و دست راست`, zh: `言语、真主之名与右手`, yue: `言語、真主之名與右手`, ja: `会話、アッラーの御名、そして右手`, ru: `Речь, имя Аллаха и правая рука`, es: `Hablar, el nombre de Al-lah y la mano derecha`, ko: `대화, 알라의 이름, 그리고 오른손`, ta: `பேசுதல், அல்லாஹ்வின் பெயர் மற்றும் வலது கை`, si: `කථා කිරීම, අල්ලාහ්ගේ නාමය සහ දකුණු අත` },
  speech_p1: { en: `While actually relieving oneself, one does not speak, does not return salam, and does not respond to the adhan out loud (the response is made silently or after leaving).`, ms: `Semasa sedang membuang air, seseorang tidak bercakap, tidak menjawab salam, dan tidak menjawab azan dengan suara (jawapan diberi secara senyap atau selepas keluar).`, tur: `Def-i hâcet sırasında kişi konuşmaz, selam almaz, ezanı da sesle karşılamaz (cevap sessiz olarak veya çıktıktan sonra verilir).`, urd: `قضائے حاجت کے دوران بندہ نہ بولے، نہ سلام کا جواب دے، اور نہ اذان کا جواب اونچی آواز میں دے (جواب دل میں یا نکلنے کے بعد دیا جائے)۔`, ben: `প্রস্রাব-পায়খানার সময় ব্যক্তি কথা বলবে না, সালামের উত্তর দেবে না এবং আজানের জবাব উচ্চস্বরে দেবে না (জবাব নীরবে অথবা বেরিয়ে আসার পর দেওয়া হয়)।`, fas: `هنگام قضای حاجت، شخص سخن نمی‌گوید، پاسخ سلام نمی‌دهد و اذان را با صدا اجابت نمی‌کند (پاسخ در دل یا پس از خروج داده می‌شود).`, zh: `方便之际，勿言、勿答色兰、勿出声应邦克（默应之，或出后再应）。`, yue: `方便之際，勿言、勿答色蘭、勿出聲應邦克（默應之，或出後再應）。`, ja: `用を足している間は、話さず、サラームに応えず、アザーンにも声を出して応じない（心の中で応じるか、出てから応じる）。`, ru: `Во время самого отправления нужды человек не разговаривает, не отвечает на салам и не отвечает на азан вслух (ответ произносится про себя или после выхода).`, es: `Mientras se hace realmente la necesidad, no se habla, no se responde al salam ni al adhan en voz alta (la respuesta se hace en silencio o al salir).`, ko: `실제로 용변을 보는 동안에는 말하지 않고, 살람에 답하지 않으며, 아잔에도 소리 내어 응답하지 않는다 (응답은 마음속으로 하거나 나온 후에 한다).`, ta: `இயற்கை உபாதையின் நடுவே பேசாதிருக்க வேண்டும், ஸலாமுக்கு பதில் சொல்லக்கூடாது, மற்றும் அதானை உரக்கச் சொல்லிப் பதில் சொல்லக்கூடாது (பதிலை மௌனமாக அல்லது வெளியேறியப் பிறகு சொல்ல வேண்டும்).`, si: `අවශ්‍යතාව සිදු කරන අවස්ථාවේ කථා නොකළ යුතුය, සලාමයට පිළිතුරු නොදිය යුතුය, සහ අදාන්හට හඩකින් පිළිතුරු නොදිය යුතුය (පිළිතුර නිහඬව හෝ පිටව යාමෙන් පසුව සිදු කරයි).` },
  speech_p2: { en: `One should not carry anything on which Allah's name is written, including a mushaf, unless there is a real need and it is kept covered. Modern phones with the Qur'an app in the pocket are, in the view of most contemporary scholars, permissible because the text is not physically written on the device, but leaving the phone outside is more cautious and closer to the spirit of the ruling.`, ms: `Seseorang tidak boleh membawa sesuatu yang tertulis nama Allah, termasuk mushaf, kecuali ada keperluan sebenar dan ia disimpan dalam keadaan tertutup. Telefon moden yang mengandungi aplikasi al-Quran di dalam poket, menurut majoriti ulama kontemporari, dibenarkan kerana teks tidak tertulis secara fizikal pada peranti, namun meninggalkan telefon di luar adalah lebih berhati-hati dan lebih hampir kepada semangat hukum.`, tur: `Üzerinde Allah'ın adı yazılı bir şey, mushaf dâhil, gerçek bir ihtiyaç olmadıkça ve örtülü tutulmadıkça yanında götürülmez. Cebinde Kur'an uygulaması bulunan modern telefonlar, çağdaş âlimlerin çoğuna göre metin cihaza fiziksel olarak yazılmadığı için câizdir; ancak telefonu dışarıda bırakmak daha ihtiyatlıdır ve hükmün ruhuna daha yakındır.`, urd: `کوئی ایسی چیز جس پر اللہ کا نام لکھا ہو، بشمول مصحف، ساتھ نہیں لے جانی چاہیے، الا یہ کہ حقیقی ضرورت ہو اور اسے ڈھانپ کر رکھا جائے۔ جدید فون جن کی جیب میں قرآن ایپ ہو، اکثر معاصر علماء کی رائے میں جائز ہے، کیونکہ متن آلے پر جسمانی طور پر لکھا نہیں ہوتا، لیکن فون کو باہر چھوڑنا زیادہ احتیاط اور حکم کی روح کے قریب ہے۔`, ben: `আল্লাহর নাম লেখা কোনো কিছু, মুসহাফ সহ, প্রকৃত প্রয়োজন ছাড়া ও ঢেকে না রেখে বহন করা উচিত নয়। পকেটে কুরআন অ্যাপ থাকা আধুনিক ফোন সমকালীন অধিকাংশ আলিমের মতে অনুমোদিত, কারণ পাঠ্য ডিভাইসে শারীরিকভাবে লেখা নেই; তবে ফোন বাইরে রেখে যাওয়া অধিক সতর্কতা ও বিধানের মর্মের নিকটবর্তী।`, fas: `چیزی که نام خدا بر آن نوشته باشد، از جمله مصحف، جز به ضرورت واقعی و در حالِ پوشیده، همراه برده نمی‌شود. تلفن‌های جدید که برنامهٔ قرآن در جیب حمل می‌کنند، به نظرِ اکثر علمای معاصر جایز است زیرا متن به‌طور فیزیکی روی دستگاه نوشته نشده است؛ اما گذاشتن تلفن در بیرون محتاطانه‌تر و نزدیک‌تر به روح حکم است.`, zh: `凡上有真主名字之物，包括穆斯哈夫，若非确有必要且加以遮蔽，皆不当携入。今之手机内藏《古兰》程序者，多数当代学者以为可携，因经文非物理书写于机具；然置之于外更为审慎，亦更合乎教旨之意。`, yue: `凡上有真主名字之物，包括穆斯哈夫，若非確有必要且加以遮蔽，皆不當攜入。今之手機內藏《古蘭》程式者，多數當代學者以為可攜，因經文非物理書寫於機具；然置之於外更為審慎，亦更合乎教旨之意。`, ja: `アッラーの御名が書かれた物、ムスハフを含め、正当な必要があり覆っている場合を除き携えてはならない。ポケットにクルアーンアプリのある現代のスマートフォンは、多くの現代の学者の見解では、テキストが物理的に機器へ書かれていないため許容される。ただし外に置いておく方が慎重であり、規定の精神に近い。`, ru: `Не следует брать с собой ничего, на чём написано имя Аллаха, включая мусхаф, если нет реальной необходимости и оно не прикрыто. Современные телефоны с приложением Корана в кармане, по мнению большинства современных учёных, дозволены, поскольку текст физически не написан на устройстве; однако оставить телефон снаружи осторожнее и ближе к духу предписания.`, es: `No se debe llevar nada en lo que esté escrito el nombre de Al-lah, incluido el mushaf, salvo verdadera necesidad y estando cubierto. Los teléfonos modernos con la app del Corán en el bolsillo, a juicio de la mayoría de los sabios contemporáneos, se permiten porque el texto no está físicamente escrito en el dispositivo; pero dejar el teléfono fuera es más prudente y más cercano al espíritu del fallo.`, ko: `알라의 이름이 새겨진 어떤 것도, 무스하프를 포함하여, 실질적 필요와 덮인 상태가 아니면 지녀서는 안 된다. 주머니에 꾸란 앱이 든 현대 휴대전화는 대부분의 현대 학자 견해로는 텍스트가 기기에 물리적으로 쓰인 것이 아니므로 허용된다; 그러나 전화를 밖에 두는 편이 더 신중하며 규정의 정신에 가깝다.`, ta: `அல்லாஹ்வின் பெயர் எழுதப்பட்ட எதையும், முஸ்ஹஃப் உட்பட, உண்மையான தேவை இல்லாமல் மற்றும் மூடி வைக்கப்படாமல் எடுத்துச் செல்லக்கூடாது. பாக்கெட்டில் குர்ஆன் ஆப் உள்ள நவீன தொலைபேசிகள், சமகால அறிஞர்களில் பெரும்பாலோர் கருத்துப்படி, உரை சாதனத்தில் உடல்ரீதியாக எழுதப்படவில்லை என்பதால் அனுமதிக்கப்படுகின்றன; ஆனால் தொலைபேசியை வெளியே விட்டு வைப்பது கூடுதல் எச்சரிக்கை மற்றும் விதியின் ஆன்மாவுக்கு நெருக்கமானது.`, si: `අල්ලාහ්ගේ නාමය ලියා ඇති කිසිවක්, මුස්හෆය ඇතුළුව, සත්‍ය අවශ්‍යතාවක් නොමැති නම් සහ වසා නොතැබූ නම් ගෙන යා යුතු නොවේ. පොකැට්ටුවේ කුර්ආන් යෙදුමක් සහිත නවීන දුරකථන, බොහෝ සමකාලීන විද්වතුන්ගේ මතය අනුව, පෙළ භෞතිකව උපාංගය මත ලියා නොමැති බැවින් අනුමතයි; නමුත් දුරකථනය පිටත තැබීම වඩාත් ප්‍රවේශම්කාරී වන අතර නීතියේ ආත්මයට ආසන්නය.` },
  speech_p3: { en: `Cleansing (istinja with water, or istijmar with clean stones or their equivalent, such as toilet paper) must be done with the left hand. The Prophet ﷺ forbade the right hand from cleansing after the toilet.`, ms: `Bersuci (istinja dengan air, atau istijmar dengan batu bersih atau sepertinya seperti tisu tandas) mesti dilakukan dengan tangan kiri. Nabi ﷺ melarang penggunaan tangan kanan untuk bersuci selepas buang air.`, tur: `Temizlik (su ile istincâ ya da temiz taş veya benzeri, tuvalet kâğıdı gibi, ile istincmâr) sol el ile yapılır. Peygamber ﷺ, tuvaletten sonra sağ elle temizlenmeyi yasakladı.`, urd: `صفائی (پانی سے استنجا، یا صاف پتھر یا اس کے مثل مثلاً ٹشو سے استجمار) بائیں ہاتھ سے کی جائے۔ نبی ﷺ نے بیت الخلا کے بعد دائیں ہاتھ سے صفائی سے منع فرمایا۔`, ben: `পরিচ্ছন্নতা (পানি দিয়ে ইস্তিনজা, বা পরিষ্কার পাথর অথবা তার সমতুল্য যেমন টিস্যু দিয়ে ইস্তিজমার) বাম হাত দিয়ে করতে হবে। নবী ﷺ শৌচাগারের পর ডান হাত দিয়ে পরিচ্ছন্ন করা নিষেধ করেছেন।`, fas: `پاکیزگی (استنجا با آب یا استجمار با سنگ‌های پاک یا مانند آن، مانند دستمال کاغذی) با دست چپ انجام می‌شود. پیامبر ﷺ از پاک‌کردن با دست راست پس از قضای حاجت نهی فرمود.`, zh: `洁净（以水行「伊斯提奈」，或以净石或其类，如卫生纸，行「伊斯提吉马尔」）当以左手为之。先知 ﷺ 禁人如厕后以右手清洁。`, yue: `潔淨（以水行「伊斯提奈」，或以淨石或其類，如衛生紙，行「伊斯提吉馬爾」）當以左手為之。先知 ﷺ 禁人如廁後以右手清潔。`, ja: `清め（水によるイスティンジャー、清らかな石またはそれに相当するもの、たとえばトイレットペーパーによるイスティジュマール）は左手で行う。預言者 ﷺ は用便のあとの清めに右手を用いることを禁じられた。`, ru: `Очищение (истинджа водой или истиджмар чистыми камнями либо их эквивалентом, например туалетной бумагой) совершается левой рукой. Пророк ﷺ запретил очищаться после туалета правой рукой.`, es: `La limpieza (istinja con agua, o istijmar con piedras limpias o su equivalente, como papel higiénico) se hace con la mano izquierda. El Profeta ﷺ prohibió usar la mano derecha para limpiarse tras el retrete.`, ko: `세정(물로 하는 이스틴자, 혹은 깨끗한 돌이나 그에 상응하는 것 예컨대 화장지로 하는 이스티즈마르)은 왼손으로 해야 한다. 예언자 ﷺ 께서는 용변 후 오른손으로 세정하는 것을 금하셨다.`, ta: `தூய்மைப்படுத்துதல் (நீரால் இஸ்திஞ்ஜா, அல்லது சுத்தமான கற்கள் அல்லது அதற்கு இணையான டாய்லெட் காகிதம் போன்றவற்றால் இஸ்திஜ்மார்) இடது கையால் செய்யப்பட வேண்டும். கழிப்பறைக்குப் பின் வலது கையால் சுத்தம் செய்வதை நபி ﷺ தடை செய்தார்.`, si: `පිරිසිදු කිරීම (ජලයෙන් ඉස්තින්ජා, හෝ පිරිසිදු ගල් හෝ ඒවාට සමාන දේ වන වැසිකිළි කඩදාසි වැනි දේවලින් ඉස්තිජ්මාර්) වම් අතින්ම කළ යුතුය. වැසිකිළියෙන් පසු දකුණු අතින් පිරිසිදු කිරීම නබි ﷺ තුමා තහනම් කළහ.` },
  speech_source: { en: `Source: al-Bukhari 153, Muslim 267 (Abu Qatada).`, ms: `Sumber: al-Bukhari 153, Muslim 267 (Abu Qatada).`, tur: `Kaynak: Buhârî 153, Müslim 267 (Ebû Katâde).`, urd: `ماخذ: بخاری ۱۵۳، مسلم ۲۶۷ (ابو قتادہ)۔`, ben: `উৎস: বুখারি ১৫৩, মুসলিম ২৬৭ (আবু কাতাদা)।`, fas: `منبع: بخاری ۱۵۳، مسلم ۲۶۷ (ابوقتاده).`, zh: `出处：布哈里 153、穆斯林 267（艾布·卡塔达）。`, yue: `出處：布哈里 153、穆斯林 267（艾布·卡塔達）。`, ja: `出典：ブハーリー 153、ムスリム 267（アブー・カターダ）。`, ru: `Источник: аль-Бухари 153, Муслим 267 (Абу Катада).`, es: `Fuente: al-Bukhari 153, Muslim 267 (Abu Qatada).`, ko: `출처: 알부카리 153, 무슬림 267 (아부 까따다).`, ta: `மூலம்: புகாரி 153, முஸ்லிம் 267 (அபூ கதாதா).`, si: `මූලාශ්‍රය: බුකාරි 153, මුස්ලිම් 267 (අබූ කතාදා).` },

  istinja_h: { en: `Istinja and Istijmar`, ms: `Istinja dan Istijmar`, tur: `İstincâ ve İstincmâr`, urd: `استنجا اور استجمار`, ben: `ইস্তিনজা ও ইস্তিজমার`, fas: `استنجا و استجمار`, zh: `伊斯提奈与伊斯提吉马尔`, yue: `伊斯提奈與伊斯提吉馬爾`, ja: `イスティンジャーとイスティジュマール`, ru: `Истинджа и истиджмар`, es: `Istinja e Istijmar`, ko: `이스틴자와 이스티즈마르`, ta: `இஸ்திஞ்ஜா மற்றும் இஸ்திஜ்மார்`, si: `ඉස්තින්ජා සහ ඉස්තිජ්මාර්` },
  istinja_p1: { en: `Istinja is cleansing the place of exit with water until it is clean and the traces of impurity are removed. Istijmar is cleansing with clean stones, tissue, or any absorbent solid material (traditionally an odd number, minimum three).`, ms: `Istinja ialah membersihkan tempat keluar dengan air sehingga bersih dan kesan najis hilang. Istijmar ialah membersihkan dengan batu bersih, tisu, atau bahan pepejal penyerap yang lain (tradisinya dengan bilangan ganjil, minimum tiga).`, tur: `İstincâ, çıkış yerini su ile temizleyerek necâset izinin kalmamasıdır. İstincmâr ise temiz taşlarla, kâğıt mendil ile veya benzer bir emici katı ile temizlemektir (geleneksel olarak tek sayı, asgarî üç).`, urd: `استنجا کا مطلب مقامِ خروج کو پانی سے صاف کرنا ہے یہاں تک کہ ناپاکی کے آثار مٹ جائیں۔ استجمار صاف پتھروں، ٹشو یا کسی جاذب ٹھوس چیز سے صفائی کرنا ہے (روایتاً طاق تعداد، کم از کم تین)۔`, ben: `ইস্তিনজা হলো বহির্গমনের স্থানটি পানি দিয়ে পরিষ্কার করা যতক্ষণ না তা পরিচ্ছন্ন হয় এবং অপবিত্রতার চিহ্ন দূর হয়। ইস্তিজমার হলো পরিষ্কার পাথর, টিস্যু বা অনুরূপ শোষণকারী কঠিন বস্তু দিয়ে পরিষ্কার করা (ঐতিহ্যগতভাবে বিজোড় সংখ্যা, ন্যূনতম তিনটি)।`, fas: `استنجا یعنی پاک‌کردنِ محل خروج با آب تا اثر نجاست از بین برود. استجمار یعنی پاک‌سازی با سنگ‌های پاک، دستمال یا مواد جامدِ جاذب مشابه (به‌طور سنتی به شمار فرد، حداقل سه بار).`, zh: `伊斯提奈者，以水洁排泄之处直至洁净、无余污也。伊斯提吉马尔者，以净石、纸巾或类似之吸性固体行洁净（传统上取奇数，至少三次）。`, yue: `伊斯提奈者，以水潔排泄之處直至潔淨、無餘污也。伊斯提吉馬爾者，以淨石、紙巾或類似之吸性固體行潔淨（傳統上取奇數，至少三次）。`, ja: `イスティンジャーは、排泄口を水で清めて汚れの跡が残らないようにすることです。イスティジュマールは、清らかな石や紙、あるいは同等の吸収性のある固体で清めることです（伝統的には奇数回、最少で三回）。`, ru: `Истинджа, очищение места выхода водой до полной чистоты и удаления следов нечистоты. Истиджмар, очищение чистыми камнями, бумагой или иным впитывающим твёрдым материалом (традиционно нечётное число раз, минимум три).`, es: `Istinja es limpiar el lugar de salida con agua hasta que quede limpio y desaparezcan los restos de impureza. Istijmar es limpiar con piedras limpias, papel u otro material sólido absorbente (tradicionalmente un número impar, mínimo tres).`, ko: `이스틴자는 배출구를 물로 씻어 부정의 흔적이 사라질 때까지 깨끗이 하는 것이다. 이스티즈마르는 깨끗한 돌, 화장지 또는 이에 상응하는 흡수성 고체로 세정하는 것(전통적으로 홀수 횟수, 최소 세 번)이다.`, ta: `இஸ்திஞ்ஜா என்பது வெளியேற்றத்தின் இடத்தை நீரால் சுத்தமாகும் வரையிலும், அசுத்தத்தின் அடையாளங்கள் நீங்கும் வரையிலும் கழுவுவதாகும். இஸ்திஜ்மார் என்பது சுத்தமான கற்கள், டிஷ்யூ அல்லது அதே போன்ற உறிஞ்சும் திடப்பொருள் கொண்டு சுத்தம் செய்வது (பாரம்பரியமாக ஒற்றை எண், குறைந்தபட்சம் மூன்று).`, si: `ඉස්තින්ජා යනු පිටවීමේ ස්ථානය ජලයෙන් අශුද්ධ අංශුවක් නොපවතින තුරු පිරිසිදු කිරීමයි. ඉස්තිජ්මාර් යනු පිරිසිදු ගල්, කඩදාසි හෝ ඒවාට සමාන අවශෝෂක ඝන ද්‍රව්‍යවලින් පිරිසිදු කිරීමයි (සම්ප්‍රදායිකව ඔත්තේ ගණනකින්, අවම වශයෙන් තුනකින්).` },
  istinja_p2: { en: `The classical rule across all four schools: water is superior; if only solids are available, at least three wipes are used until the place is clean. Combining both is the most complete Sunnah, water after solids.`, ms: `Kaedah klasik merentasi keempat-empat mazhab: air lebih utama; jika hanya bahan pepejal yang ada, sekurang-kurangnya tiga sapuan digunakan sehingga tempat itu bersih. Menggabungkan kedua-duanya adalah Sunnah yang paling lengkap, iaitu air selepas pepejal.`, tur: `Dört mezhepteki klasik kaide: su daha üstündür; sadece katı bulunuyorsa, temizlik sağlanana kadar en az üç silme yapılır. En eksiksiz Sünnet, katıdan sonra su ile birleştirmektir.`, urd: `چاروں مذاہب کا کلاسیکی اصول: پانی افضل ہے؛ اگر صرف ٹھوس چیز میسر ہو تو کم از کم تین بار مسح کیا جائے یہاں تک کہ جگہ صاف ہو جائے۔ سب سے مکمل سنت دونوں کو ملانا ہے، یعنی پہلے ٹھوس اور پھر پانی۔`, ben: `চার মাযহাব জুড়ে ধ্রুপদী নিয়ম: পানি উত্তম; শুধু কঠিন বস্তু থাকলে অন্তত তিনবার মুছতে হবে যতক্ষণ না স্থান পরিচ্ছন্ন হয়। উভয়টি একত্রিত করা সবচেয়ে পূর্ণাঙ্গ সুন্নাহ, কঠিন বস্তুর পর পানি।`, fas: `قاعده کلاسیک در چهار مذهب: آب برتر است؛ اگر تنها جامد در دست باشد، تا پاک شدن محل دست‌کم سه بار پاک‌کن به کار می‌رود. سنت کامل‌تر آن است که هر دو ترکیب شوند، آب پس از جامد.`, zh: `四大教派之古典规矩：水为上；若唯有固体则至少擦拭三次，直至洁净。最完备之圣行为二者兼用，先固后水。`, yue: `四大教派之古典規矩：水為上；若唯有固體則至少擦拭三次，直至潔淨。最完備之聖行為二者兼用，先固後水。`, ja: `四法学派を通じた古典の規範は次の通り。水がより優れる。固体しかない場合は、清くなるまで少なくとも三度拭う。最も完全なスンナは両者を組み合わせること、すなわち固体の後に水である。`, ru: `Классическое правило всех четырёх мазхабов: вода лучше; если доступны только твёрдые средства, применяется не менее трёх обтираний до полной чистоты. Наиболее полная Сунна, сочетать оба: воду после твёрдого.`, es: `La regla clásica en las cuatro escuelas: el agua es superior; si sólo se dispone de sólidos, se aplican al menos tres pases hasta que el lugar quede limpio. Combinar ambos es la Sunna más completa, agua después de sólidos.`, ko: `네 학파를 관통하는 고전 규정: 물이 우월하며, 고체만 있을 경우 최소 세 번 닦아 그 자리를 깨끗이 한다. 두 가지를 결합하는 것이 가장 완전한 순나이니 고체 뒤에 물을 사용하는 것이다.`, ta: `நான்கு மத்ஹபுகள் அனைத்திலும் செவ்வியல் விதி: நீர் மேலானது; திடப்பொருள் மட்டுமே இருந்தால், இடம் சுத்தமாகும் வரை குறைந்தபட்சம் மூன்று முறை துடைக்கப்படும். இருவகையையும் இணைப்பதே மிக முழுமையான ஸுன்னா, திடத்திற்குப் பின் நீர்.`, si: `සුන්නි මධ්හබ් සතරෙන්ම සම්භාව්‍ය නීතිය: ජලය උසස්ය; ඝන ද්‍රව්‍ය පමණක් තිබේ නම්, ස්ථානය පිරිසිදු වන තෙක් අවම වශයෙන් තුන් වතාවක් පිසිය යුතුය. දෙකම එකට කිරීම වඩාත් සම්පූර්ණ සුන්නාව; ඝන දෙයට පසුව ජලය.` },
  istinja_p3: { en: `Anas (ra) said: "The Prophet ﷺ used to enter the toilet, and I used to bring him water for him to wash himself with."`, ms: `Anas (ra) berkata: "Nabi ﷺ akan masuk ke tandas, dan aku akan membawakan air untuknya membersihkan diri."`, tur: `Enes (r.a.) buyurdu: "Peygamber ﷺ tuvalete girerdi, ben de kendisine yıkanacağı suyu getirirdim."`, urd: `انس (رض) نے فرمایا: "نبی ﷺ بیت الخلا جاتے، اور میں ان کے استعمال کے لیے پانی لاتا۔"`, ben: `আনাস (রা) বলেন: "নবী ﷺ শৌচাগারে যেতেন এবং আমি তাঁর ব্যবহারের জন্য পানি নিয়ে যেতাম।"`, fas: `انس (رض) گفت: «پیامبر ﷺ به دستشویی می‌رفت و من برایش آب می‌آوردم تا با آن پاکیزه شود.»`, zh: `阿奈斯（愿主喜之）云：「先知 ﷺ 常入厕，我为其携水以供洁净。」`, yue: `阿奈斯（願主喜之）云：「先知 ﷺ 常入廁，我為其攜水以供潔淨。」`, ja: `アナス（ラ）は言われた。「預言者 ﷺ は厠に入られたので、私は身を清めるための水をお持ちしたものであった。」`, ru: `Анас (ра) сказал: «Пророк ﷺ входил в отхожее место, а я приносил ему воду, чтобы он ею омывался».`, es: `Anas (ra) dijo: «El Profeta ﷺ entraba al retrete, y yo le llevaba agua para que se lavara.»`, ko: `아나스(라)께서 말씀하시길: "예언자 ﷺ 께서 화장실에 들어가시면 나는 그분께서 씻으실 수 있도록 물을 가져다드렸다."`, ta: `அனஸ் (ரலி) கூறினார்: "நபி ﷺ கழிப்பறைக்குச் செல்வார், அவர் தூய்மைப்படுத்திக்கொள்ள நான் தண்ணீர் கொண்டு வருவேன்."`, si: `අනස් (රළි) පැවසුවාය: "නබි ﷺ තුමා වැසිකිළියට වඩිත්. මම ඔහුට තමන් සෝදාගැනීමට ජලය ගෙන ආවෙමි."` },
  istinja_source: { en: `Source: al-Bukhari 217, Muslim 271.`, ms: `Sumber: al-Bukhari 217, Muslim 271.`, tur: `Kaynak: Buhârî 217, Müslim 271.`, urd: `ماخذ: بخاری ۲۱۷، مسلم ۲۷۱۔`, ben: `উৎস: বুখারি ২১৭, মুসলিম ২৭১।`, fas: `منبع: بخاری ۲۱۷، مسلم ۲۷۱.`, zh: `出处：布哈里 217、穆斯林 271。`, yue: `出處：布哈里 217、穆斯林 271。`, ja: `出典：ブハーリー 217、ムスリム 271。`, ru: `Источник: аль-Бухари 217, Муслим 271.`, es: `Fuente: al-Bukhari 217, Muslim 271.`, ko: `출처: 알부카리 217, 무슬림 271.`, ta: `மூலம்: புகாரி 217, முஸ்லிம் 271.`, si: `මූලාශ්‍රය: බුකාරි 217, මුස්ලිම් 271.` },

  wisdom_h: { en: `The Wisdom Behind These Etiquettes`, ms: `Hikmah di Sebalik Adab Ini`, tur: `Bu Âdâbın Ardındaki Hikmet`, urd: `ان آداب کے پیچھے حکمت`, ben: `এই আদবগুলোর পিছনের হিকমাহ`, fas: `حکمت پشت این آداب`, zh: `此等礼节之背后智慧`, yue: `此等禮節之背後智慧`, ja: `これらの作法の背後にある叡智`, ru: `Мудрость за этими правилами`, es: `La sabiduría tras estas etiquetas`, ko: `이 예절 뒤에 있는 지혜`, ta: `இந்த ஆதாபுகளின் பின்னாலுள்ள ஞானம்`, si: `මෙම අදාබ්හි පිටුපස ඇති ප්‍රඥාව` },
  wisdom_intro: { en: `Islam does not treat any moment of a Muslim's day as too private for guidance. The etiquettes of the toilet are a small door onto a large teaching:`, ms: `Islam tidak menganggap sebarang saat dalam hari seorang Muslim terlalu peribadi untuk mendapat panduan. Adab-adab tandas adalah pintu kecil kepada pengajaran yang besar:`, tur: `İslam, bir Müslümanın gününün hiçbir anını rehberlik için fazla mahrem saymaz. Tuvalet âdâbı, büyük bir öğretiye açılan küçük bir kapıdır:`, urd: `اسلام ایک مسلمان کے دن کے کسی بھی لمحے کو ہدایت کے لیے بہت نجی نہیں سمجھتا۔ بیت الخلا کے آداب ایک بڑی تعلیم کی طرف کھلنے والا چھوٹا سا دروازہ ہیں:`, ben: `ইসলাম কোনো মুসলিমের দিনের কোনো মুহূর্তকেই দিকনির্দেশনার জন্য খুব ব্যক্তিগত মনে করে না। শৌচাগারের আদব একটি বড় শিক্ষার দিকে খোলা ছোট্ট এক দরজা:`, fas: `اسلام هیچ لحظه‌ای از روزِ مسلمان را برای هدایت‌شدن بیش از حد خصوصی نمی‌داند. آداب دستشویی درِ کوچکی به سوی آموزه‌ای بزرگ است:`, zh: `伊斯兰不视穆斯林一日之任何时刻为过私而不受引导。厕之礼节乃通往宏大教诲之小门：`, yue: `伊斯蘭不視穆斯林一日之任何時刻為過私而不受引導。廁之禮節乃通往宏大教誨之小門：`, ja: `イスラームは、ムスリムの一日のどの瞬間も導きを受けるには私的すぎるとは見なさない。厠の作法は大きな教えへと開かれた小さな扉である。`, ru: `Ислам не считает ни один момент дня мусульманина слишком личным для руководства. Этикет отхожего места, маленькая дверь к большому учению:`, es: `El Islam no considera ningún momento del día del musulmán demasiado íntimo para ser guiado. Los modales del retrete son una pequeña puerta a una gran enseñanza:`, ko: `이슬람은 무슬림의 하루 어느 순간도 지침을 받기에 너무 사적이라 보지 않는다. 화장실의 예절은 큰 가르침으로 열리는 작은 문이다:`, ta: `இஸ்லாம் ஒரு முஸ்லிமின் நாளின் எந்த தருணத்தையும் வழிகாட்டுதலுக்கு மிக அந்தரங்கமானதாக கருதுவதில்லை. கழிப்பறை ஆதாபுகள் ஒரு பெரிய போதனையை நோக்கி திறக்கும் சிறிய கதவு:`, si: `මුස්ලිම්වරයෙකුගේ දිනයේ කිසිදු මොහොතක් මගපෙන්වීමට ඕනෑවට වඩා පෞද්ගලික යැයි ඉස්ලාමය නොසලකයි. වැසිකිළියේ අදාබ් යනු මහත් අධ්‍යාපනයකට විවෘත වන කුඩා දොරකි:` },
  wisdom_1: { en: `Cleanliness is half of faith (Muslim 223). It begins with the body.`, ms: `Kebersihan adalah separuh daripada iman (Muslim 223). Ia bermula dengan tubuh.`, tur: `Temizlik imanın yarısıdır (Müslim 223). O, bedenle başlar.`, urd: `پاکیزگی نصف ایمان ہے (مسلم ۲۲۳)۔ یہ بدن سے شروع ہوتی ہے۔`, ben: `পরিচ্ছন্নতা ঈমানের অর্ধেক (মুসলিম ২২৩)। এটি শরীর থেকে শুরু হয়।`, fas: `پاکیزگی نیمی از ایمان است (مسلم ۲۲۳). این با بدن آغاز می‌شود.`, zh: `洁净乃信仰之半（穆斯林 223）。始于身体。`, yue: `潔淨乃信仰之半（穆斯林 223）。始於身體。`, ja: `清潔は信仰の半ばである（ムスリム 223）。それは身体から始まる。`, ru: `Чистота, половина веры (Муслим 223). Она начинается с тела.`, es: `La limpieza es la mitad de la fe (Muslim 223). Comienza por el cuerpo.`, ko: `청결은 신앙의 절반이다 (무슬림 223). 그것은 몸에서 시작된다.`, ta: `தூய்மை நம்பிக்கையின் பாதி (முஸ்லிம் 223). அது உடலிலிருந்து தொடங்குகிறது.`, si: `පිරිසිදුකම විශ්වාසයේ අඩකි (මුස්ලිම් 223). එය ශරීරයෙන් ආරම්භ වේ.` },
  wisdom_2: { en: `Modesty, the toilet is a private place, entered discreetly, without frivolity.`, ms: `Kesopanan, tandas adalah tempat peribadi, dimasuki dengan sopan, tanpa kejenakaan.`, tur: `Hayâ, tuvalet mahrem bir yerdir; sessizce, oyunbaz olmadan girilir.`, urd: `حیا، بیت الخلا ایک نجی جگہ ہے، جس میں خاموشی سے، بلا مذاق داخل ہوا جائے۔`, ben: `শালীনতা, শৌচাগার একটি ব্যক্তিগত স্থান, সেখানে বিনয়ের সাথে, চপলতা ছাড়া প্রবেশ করা হয়।`, fas: `حیا؛ دستشویی مکانی خصوصی است، آرام و بی‌سبک‌سری وارد آن می‌شویم.`, zh: `谦耻。厕为隐私之所，静入而无戏。`, yue: `謙恥。廁為隱私之所，靜入而無戲。`, ja: `慎み。厠は私的な場所であり、目立たず、戯れなく入る。`, ru: `Скромность. Отхожее место, уединённое, входить в него следует сдержанно и без легкомыслия.`, es: `Pudor. El retrete es un lugar privado, se entra con discreción, sin frivolidad.`, ko: `수줍음. 화장실은 사적인 공간이며, 조용히, 경솔함 없이 들어간다.`, ta: `நாணம். கழிப்பறை ஒரு அந்தரங்க இடம், மென்மையாக, விளையாட்டு இன்றி நுழையப்படுவது.`, si: `ලජ්ජාව. වැසිකිළිය පෞද්ගලික ස්ථානයකි; නිහඬව, විහිළුවකින් තොරව ඇතුළු වේ.` },
  wisdom_3: { en: `Constant remembrance, the servant enters seeking refuge, leaves seeking forgiveness. Even here, the heart is turned to Allah.`, ms: `Ingatan berterusan, hamba masuk memohon perlindungan, keluar memohon keampunan. Bahkan di sini, hati diarahkan kepada Allah.`, tur: `Sürekli zikir, kul sığınarak girer, mağfiret dileyerek çıkar. Burada bile kalp Allah'a yönelir.`, urd: `مسلسل ذکر، بندہ پناہ مانگتے ہوئے داخل ہوتا ہے، مغفرت طلب کرتے ہوئے نکلتا ہے۔ یہاں بھی دل اللہ کی طرف متوجہ رہتا ہے۔`, ben: `স্থায়ী স্মরণ, বান্দা আশ্রয় প্রার্থনা করে প্রবেশ করে, ক্ষমা প্রার্থনা করে বের হয়। এখানেও হৃদয় আল্লাহর দিকে ফিরে থাকে।`, fas: `یاد پیوسته؛ بنده با پناه‌جویی وارد می‌شود و با استغفار بیرون می‌رود. حتی اینجا نیز دل به سوی خدا رو دارد.`, zh: `恒常之念主。仆入而求护，出而求赦。即于此处，心亦向真主。`, yue: `恆常之念主。僕入而求護，出而求赦。即於此處，心亦向真主。`, ja: `絶えざる想起。僕は加護を求めて入り、赦しを求めて出る。ここにおいても心はアッラーへ向けられる。`, ru: `Постоянное поминание. Раб входит, прибегая к защите, и выходит, прося прощения. Даже здесь сердце обращено к Аллаху.`, es: `Recuerdo constante. El siervo entra pidiendo refugio y sale pidiendo perdón. Incluso aquí, el corazón se vuelve a Al-lah.`, ko: `끊임없는 상기. 종은 피난을 구하며 들어가고, 용서를 구하며 나온다. 이곳에서도 마음은 알라를 향한다.`, ta: `இடையறாத நினைவு. அடியான் அடைக்கலம் தேடி நுழைகிறார், மன்னிப்பு தேடி வெளியேறுகிறார். இங்கும் இதயம் அல்லாஹ்வை நோக்கியே இருக்கிறது.`, si: `නොකඩවා සිහිකිරීම. දේවසේවකයා රැකවරණය පතමින් ඇතුළු වේ, සමාව පතමින් පිටව යයි. මෙහිද හදවත අල්ලාහ් වෙතට යොමු වේ.` },
  wisdom_4: { en: `Distinction of the right and the left, an outward habit that trains an inward preference for what is noble.`, ms: `Pembezaan antara kanan dan kiri, tabiat luaran yang melatih pilihan dalaman untuk perkara yang mulia.`, tur: `Sağ ile solun ayırt edilmesi, dışsal bir alışkanlıktır ki içteki asalet tercihini eğitir.`, urd: `دائیں اور بائیں کا فرق، ایک بیرونی عادت جو باطن میں شریف چیز کو ترجیح دینا سکھاتی ہے۔`, ben: `ডান ও বামের পার্থক্য, একটি বাহ্যিক অভ্যাস যা মহৎ কিছুর প্রতি অন্তরের পছন্দকে গড়ে তোলে।`, fas: `تمایز راست و چپ؛ عادتی بیرونی که ترجیحِ درونی به سوی شرافت را می‌پرورد.`, zh: `辨右辨左，外之习也，所以训内心尚贵之偏好。`, yue: `辨右辨左，外之習也，所以訓內心尚貴之偏好。`, ja: `右と左の区別。高貴なものへの内なる偏りを養う、外的な習慣。`, ru: `Различение правого и левого, внешняя привычка, воспитывающая внутреннее предпочтение благородного.`, es: `Distinción entre lo derecho y lo izquierdo, un hábito externo que educa una preferencia interna por lo noble.`, ko: `오른쪽과 왼쪽의 구분. 고귀한 것을 향한 내면의 선호를 훈련시키는 외적 습관.`, ta: `வலது இடது என்ற பாகுபாடு; உள்ளத்திற்குள் மேன்மையானதை விரும்பும் அறவை பயிற்றுவிக்கும் வெளிப்புற பழக்கம்.`, si: `දකුණ හා වම වෙන් කිරීම; ගෞරවනීය දෙයට අභ්‍යන්තර නැඹුරුවක් සදන බාහිර පුරුද්දකි.` },
  wisdom_5: { en: `Consideration for others, do not soil the water they drink from, the paths they walk, or the shade they rest in.`, ms: `Timbang rasa terhadap orang lain, jangan cemarkan air yang mereka minum, jalan yang mereka lalui, atau tempat teduh mereka berehat.`, tur: `Başkalarını gözetmek, içtikleri suyu, yürüdükleri yolu ya da dinlendikleri gölgeyi kirletmemek.`, urd: `دوسروں کا خیال، جس پانی سے وہ پیتے ہیں، جن راستوں پر چلتے ہیں، اور جن سایوں میں آرام کرتے ہیں، انہیں گندا نہ کرو۔`, ben: `অন্যদের প্রতি বিবেচনা, তারা যে পানি পান করে, যে পথে চলে, বা যে ছায়ায় বিশ্রাম নেয় তা নোংরা করো না।`, fas: `توجه به دیگران؛ آب نوشیدنی، راه‌های تردد و سایه‌های استراحت آنان را نیالایید.`, zh: `顾及他人。勿污其所饮之水、所行之路、所憩之荫。`, yue: `顧及他人。勿污其所飲之水、所行之路、所憩之蔭。`, ja: `他者への配慮。人々が飲む水も、歩く道も、憩う日陰も汚さない。`, ru: `Уважение к другим, не оскверняй воды, из которой они пьют, дорог, по которым они ходят, и тени, где они отдыхают.`, es: `Consideración por los demás, no ensucies el agua que beben, los caminos por los que andan, ni la sombra en la que descansan.`, ko: `타인에 대한 배려. 그들이 마시는 물, 그들이 걷는 길, 그들이 쉬는 그늘을 더럽히지 말라.`, ta: `மற்றவர்களைப் பற்றி கருத்தில் கொள்ளுதல்; அவர்கள் குடிக்கும் நீரையோ, நடக்கும் பாதைகளையோ, ஓய்வெடுக்கும் நிழலையோ கறையாக்காதீர்கள்.`, si: `අන් අය කෙරෙහි සැලකිල්ල. ඔවුන් පානය කරන ජලය, ගමන් යන මාර්ග හෝ විවේකය ලබන සෙවන අපිරිසිදු නොකරන්න.` },
  wisdom_close: { en: `A companion of the polytheists once mocked the Muslims saying: "Your Prophet has taught you everything, even how to relieve yourselves." Salman al-Farisi (ra) replied: "Yes, he has forbidden us from facing the qiblah, from cleansing with the right hand, from using fewer than three stones, and from using dung or bone."`, ms: `Seorang musyrik pernah mengejek orang Muslim, katanya: "Nabi kamu telah mengajar kamu segala-galanya, bahkan cara membuang air." Salman al-Farisi (ra) menjawab: "Ya, beliau telah melarang kami menghadap kiblat, bersuci dengan tangan kanan, menggunakan kurang daripada tiga batu, dan menggunakan najis kering atau tulang."`, tur: `Müşriklerden biri bir gün Müslümanlarla alay ederek şöyle dedi: "Peygamberiniz size her şeyi öğretmiş, def-i hâceti bile." Selmân-ı Fârisî (r.a.) cevap verdi: "Evet, o bize kıbleye dönmeyi, sağ elle temizlenmeyi, üç taştan azıyla temizlenmeyi ve tezek ya da kemik kullanmayı yasakladı."`, urd: `مشرکین کے ایک آدمی نے مسلمانوں کا مذاق اڑاتے ہوئے کہا: "تمہارے نبی نے تمہیں سب کچھ سکھایا ہے، یہاں تک کہ قضائے حاجت کا طریقہ بھی۔" سلمان الفارسی (رض) نے جواب دیا: "ہاں، انہوں نے ہمیں قبلہ کی طرف رخ کرنے، دائیں ہاتھ سے صفائی کرنے، تین سے کم پتھر استعمال کرنے، اور گوبر یا ہڈی استعمال کرنے سے منع فرمایا۔"`, ben: `একজন মুশরিক সঙ্গী একবার মুসলিমদের উপহাস করে বলল: "তোমাদের নবী তোমাদের সবকিছু শিখিয়েছেন, এমনকি প্রস্রাব-পায়খানার পদ্ধতিও।" সালমান আল-ফারিসি (রা) উত্তর দিলেন: "হ্যাঁ, তিনি আমাদের কিবলামুখী হতে, ডান হাতে পরিষ্কার করতে, তিনটির কম পাথর ব্যবহার করতে এবং গোবর বা হাড় ব্যবহার করতে নিষেধ করেছেন।"`, fas: `یکی از مشرکان روزی مسلمانان را دست انداخت و گفت: «پیامبرِ شما همه چیز را به شما یاد داده، حتی چگونگیِ قضای حاجت را.» سلمان فارسی (رض) پاسخ داد: «آری، ما را از رو به قبله بودن، از پاک‌شدن با دست راست، از استفاده کمتر از سه سنگ، و از به کار بردن سرگین یا استخوان بازداشته است.»`, zh: `昔一多神教徒讥诸穆斯林曰：「汝之先知连如厕之法都教了汝等。」赛勒曼·法尔西（愿主喜之）答曰：「然也。他禁我等面基卜莱、以右手洁净、用少于三块之石、以及用粪土或骨头。」`, yue: `昔一多神教徒譏諸穆斯林曰：「汝之先知連如廁之法都教了汝等。」賽勒曼·法爾西（願主喜之）答曰：「然也。他禁我等面基卜萊、以右手潔淨、用少於三塊之石、以及用糞土或骨頭。」`, ja: `かつて多神教徒の一人がムスリムたちを嘲って言った。「あなたがたの預言者は用便の仕方までも教えたのか。」サルマーン・アル＝ファールシー（ラ）は答えた。「そう、彼は我らにキブラに向かうこと、右手で清めること、三個未満の石で拭くこと、乾いた糞や骨を用いることを禁じられた。」`, ru: `Один из язычников однажды насмехался над мусульманами: «Ваш Пророк научил вас всему, даже тому, как справлять нужду». Салман аль-Фариси (ра) ответил: «Да, он запретил нам обращаться к кибле, очищаться правой рукой, пользоваться менее чем тремя камнями и использовать помёт или кость».`, es: `Un compañero de los politeístas se burló una vez de los musulmanes diciendo: «Vuestro Profeta os ha enseñado todo, hasta cómo hacer las necesidades.» Salmán al-Farisí (ra) respondió: «Sí, nos ha prohibido ponernos frente a la qiblah, limpiarnos con la mano derecha, usar menos de tres piedras y usar estiércol o hueso.»`, ko: `한 다신교인이 무슬림들을 조롱하며 말했다: "너희 예언자는 심지어 용변 보는 법까지 다 가르쳤구나." 살만 알파리시(라)께서 대답하시길: "그렇다, 그분께서는 우리에게 키블라를 향하는 것, 오른손으로 씻는 것, 세 개 미만의 돌을 사용하는 것, 그리고 배설물이나 뼈를 사용하는 것을 금하셨다."`, ta: `ஒரு முஷ்ரிக் தோழர் ஒருமுறை முஸ்லிம்களை கேலி செய்து கூறினார்: "உங்கள் நபி இயற்கை உபாதையின் முறை உட்பட எல்லாவற்றையும் உங்களுக்கு கற்பித்திருக்கிறார்." ஸல்மான் அல்-ஃபாரிஸி (ரலி) பதிலளித்தார்: "ஆம், அவர் எங்களை கிப்லாவை நோக்குவதிலிருந்தும், வலது கையால் சுத்தம் செய்வதிலிருந்தும், மூன்றுக்கும் குறைவான கற்களை பயன்படுத்துவதிலிருந்தும், சாணம் அல்லது எலும்பை பயன்படுத்துவதிலிருந்தும் தடை செய்தார்."`, si: `වරෙක බහුදේවවාදී සගයෙකු මුස්ලිම්වරුන් හට හාස්‍ය කරමින් පැවසුවේ: "ඔබගේ නබි ඔබට වැසිකිළියට යන ආකාරය පවා සියල්ල උගැන්වීය." සල්මාන් අල්-ෆාරිසි (රළි) පිළිතුරු දුන්නේය: "ඔව්, ඔහු අප කිබ්ලාව දෙසට මුහුණ ලා සිටීම, දකුණු අතින් පිරිසිදු කිරීම, ගල් තුනකට වඩා අඩුවෙන් භාවිතා කිරීම, සහ පේනුව හෝ ඇටයක් භාවිතා කිරීම තහනම් කළහ."` },
  wisdom_source: { en: `Source: Muslim 262 (Salman al-Farisi).`, ms: `Sumber: Muslim 262 (Salman al-Farisi).`, tur: `Kaynak: Müslim 262 (Selmân-ı Fârisî).`, urd: `ماخذ: مسلم ۲۶۲ (سلمان الفارسی)۔`, ben: `উৎস: মুসলিম ২৬২ (সালমান আল-ফারিসি)।`, fas: `منبع: مسلم ۲۶۲ (سلمان فارسی).`, zh: `出处：穆斯林 262（赛勒曼·法尔西）。`, yue: `出處：穆斯林 262（賽勒曼·法爾西）。`, ja: `出典：ムスリム 262（サルマーン・アル＝ファールシー）。`, ru: `Источник: Муслим 262 (Салман аль-Фариси).`, es: `Fuente: Muslim 262 (Salmán al-Farisí).`, ko: `출처: 무슬림 262 (살만 알파리시).`, ta: `மூலம்: முஸ்லிம் 262 (ஸல்மான் அல்-ஃபாரிஸி).`, si: `මූලාශ්‍රය: මුස්ලිම් 262 (සල්මාන් අල්-ෆාරිසි).` },

  label_transliteration: { en: `Transliteration`, ms: `Transliterasi`, tur: `Okunuşu`, urd: `اردو تلفظ`, ben: `উচ্চারণ`, fas: `آوانویسی`, zh: `拉丁转写`, yue: `拉丁轉寫`, ja: `ローマ字転写`, ru: `Транслитерация`, es: `Transliteración`, ko: `발음 표기`, ta: `ஒலிபெயர்ப்பு`, si: `අකුරු පෙරළුම` },
  label_meaning: { en: `Meaning`, ms: `Makna`, tur: `Anlamı`, urd: `معنی`, ben: `অর্থ`, fas: `معنا`, zh: `意义`, yue: `意義`, ja: `意味`, ru: `Значение`, es: `Significado`, ko: `의미`, ta: `பொருள்`, si: `අර්ථය` },
} as const satisfies Record<string, LangMap>;

